INSERT INTO `candidates` (`id`, `candidate_number`, `name`, `vision`, `mission`, `proker`, `photo_url`, `is_active`) VALUES
(1, 1, 'Sizzy Meyra Arini', 'Membangun siswa/i SMAN 1 Gondang yang KRITIS ( <b>K</b>reatif, <b>R</b>esponsif, <b>I</b>nspiratif, <b>T</b>anggap, <b>I</b>novatif, <b>S</b>olid).', '1. Mendengar, menampung, dan mewujudkan aspirasi siswa/i melalui tindakan nyata.\r\n2. Menjadikan setiap program bukan hanya sebuah kegiatan melainkan langkah nyata untuk menciptakan lingkungan yang lebih aktif dan berkembang secara positif.\r\n3. Meningkatkan kinerja pengurus OSIS melalui kolaborasi dengan MPK, ekstrakurikuler, dan seluruh warga sekolah.\r\n4. Menciptakan lingkungan sekolah yang aman, nyaman, inklusif, dan saling menghargai.\r\n5. Mengembangkan seluruh potensi siswa melalui kegiatan akademik maupun non akademik.', '1. Mengaktifkan kembali adanya Kangmas Mbakyu SMAN 1 Gondang.\r\n2. SMAGO Fun Run kegiatan yang melibatkan seluruh warga sekolah, terutama seluruh siswa siswi.\r\n3. SMAGO MOVE — setiap bulan satu tindakan, seperti penghijauan, gotong royong, bakti sosial, dan beberapa kegiatan lainnya.', '/admin/images/candidate_1789820460_5712.png', 1),
(2, 2, 'Prima Ardanista Zahroni', 'Mewujudkan kepemimpinan yang ABADI untuk siswa/i SMA Negeri 1 Gondang (<b>A</b>GAMIS, <b>B</b>ERKARAKTER, <b>A</b>KTIF, <b>D</b>ISIPLIN, <b>I</b>NOVATIF).', '1. Menjadikan OSIS sebagai wadah penampung aspirasi bagi siswa/i SMA Negeri 1 Gondang, mendengarkan keluhan dan harapan, lalu akan kami sampaikan ke pihak sekolah agar dapat segera ditindak lanjuti dengan cara yang solutif.\r\n2. Meningkatkan kualitas kegiatan sekolah yang (Kreatif, Inovatif, serta tanpa meninggalkan nilai moral dan agama).\r\n3. Menciptakan kolaborasi yang terbuka antara OSIS, MPK, Ekstrakulikuler, dan siswa/i SMA Negeri 1 Gondang untuk mewujudkan aspirasi dengan cara yang solutif.\r\n4. Mengembangkan Minat dan Bakat siswa dengan cara yang (Inovatif, Inklusif, dan Religius).', '1. Menciptakan website yang berjudulkan \"WISHLISTKU\" yang akan di share setiap 1 bulan sekali.\r\n2. Mengadakan kegiatan Jumat peduli.\r\n3. Mengadakan kegiatan lomba eksternal yang bertemakan \"SMAGO CUP\".', '/admin/images/candidate_1789819926_1154.png', 1);
